static int clear(void*w,float x,float y,float a,float b){return a>=8&&b>=8&&a<3192&&b<3192;}
static void ready(Combat*g){g->sp=g->maxsp;g->castDelay=0;memset(g->skillCD,0,sizeof(g->skillCD));}
static void target(Combat*g){memset(g->mobs,0,sizeof(g->mobs));CombatMob*m=&g->mobs[0];m->enabled=m->training=1;m->kind=1;m->hp=m->testMaxHP=10000;m->x=g->x+8;m->y=g->y;g->target=0;}
/* Formula/transaction regressions wait through timed spells; timing is tested separately. */
static int cast_and_finish(Combat*g,unsigned id,float x,float y){int ok=skill_cast(g,id,x,y);int n=0;while(combat_casting(g)){combat_tick(g,.05f,0,0);assert(++n<250);}return ok;}
