 // First and last new slots, both quick slots, immutable attack selection.
 WindowUI u={0};ui_open(&u,UI_SKILLS,1);u.placing=1;u.carried=59;for(int i=0;i<12;i++){u.dropSlot=i;ui_input(&u,&g,2);assert(g.hotbar[i]==59);u.placing=1;}u.dropSlot=12;ui_input(&u,&g,2);assert(quick_binding(&g,0)==59);u.placing=1;u.dropSlot=13;ui_input(&u,&g,2);assert(quick_binding(&g,1)==59);u.dropSlot=0;ui_drop_move(&u,4096);assert(u.dropSlot==12);ui_drop_move(&u,8192);assert(u.dropSlot==0);ui_drop_move(&u,2048);assert(u.dropSlot==6);for(int i=0;i<5;i++)ui_drop_move(&u,8192);assert(u.dropSlot==11);ui_drop_move(&u,8192);assert(u.dropSlot==13);
 g.hotAttack=1;g.hotSlot=0;for(int i=0;i<7;i++)skill_slot(&g,1,0);assert(g.hotAttack&&g.hotSlot==0);skill_slot(&g,0,1);assert(g.hotSlot==6&&g.hotAttack);skill_slot(&g,1,0);assert(g.hotSlot==6&&!g.hotAttack);
 hotbarStarted=0;hotbar_motion(0,0);assert(hotbar_front(0)>.999&&hotbar_front(1)<.001);hotbar_motion(1,.05);assert(fabsf(hotbar_front(0)-.5f)<.001&&hotbar_y(1)<hotbar_y(0));hotbar_motion(1,.05);assert(hotbar_front(1)>.999&&hotbar_front(0)<.001);hotbar_motion(0,.03);hotbar_motion(1,.03);for(int i=0;i<40;i++)hotbar_motion(1,.02);assert(hotbar_front(1)>.999);
